// ─────────────────────────────────────────────────────────────────────────
//  01 · parallel word count★★★
//  concepts: ExecutorService · ConcurrentHashMap · shutdown in finally
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.*;

class Exercise {

    /** Exact word counts computed on a pool of threads; the pool never leaks. */
    static Map<String, Integer> countWords(List<String> lines, int threads) {
        if (threads < 1) throw new IllegalArgumentException("threads must be >= 1");
        var counts = new ConcurrentHashMap<String, Integer>();
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        try {
            var futures = new ArrayList<Future<?>>();
            for (var line : lines) {
                futures.add(pool.submit(() -> {
                    for (var w : line.strip().split("\\s+")) {
                        if (!w.isEmpty()) counts.merge(w.toLowerCase(Locale.ROOT), 1, Integer::sum);
                    }
                }));
            }
            for (var f : futures) f.get();
        } catch (ExecutionException e) {
            throw new IllegalStateException("counting failed", e.getCause());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("interrupted", e);
        } finally {
            pool.shutdown();
        }
        return counts;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("small input is counted exactly", () -> eq(new TreeMap<>(countWords(List.of("a b", "B c", "a"), 2)), new TreeMap<>(Map.of("a", 2, "b", 2, "c", 1))));
        test("many lines on many threads lose no updates", () -> {
            var lines = new ArrayList<String>();
            for (int i = 0; i < 4000; i++) lines.add("alpha beta alpha");
            var m = countWords(lines, 8);
            eq(m.get("alpha"), 8000);
            eq(m.get("beta"), 4000);
        });
        test("one thread works too", () -> eq(countWords(List.of("x  x\tY"), 1), Map.of("x", 2, "y", 1)));
        test("no lines gives an empty map (boundary)", () -> ok(countWords(List.of(), 3).isEmpty(), "expected empty"));
        test("fewer than one thread is rejected", () -> raises(IllegalArgumentException.class, () -> countWords(List.of("a"), 0)));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

fund-java/14-threads-executors-and-synch.explanation:
Each task merges into one ConcurrentHashMap; the futures are awaited so failures surface; `finally` shuts the pool down:

```java
var counts = new ConcurrentHashMap<String, Integer>();
ExecutorService pool = Executors.newFixedThreadPool(threads);
try {
    var futures = new ArrayList<Future<?>>();
    for (var line : lines) futures.add(pool.submit(() -> {
        for (var w : line.strip().split("\\s+")) if (!w.isEmpty()) counts.merge(w.toLowerCase(Locale.ROOT), 1, Integer::sum);
    }));
    for (var f : futures) f.get();
} catch (ExecutionException e) {
    throw new IllegalStateException("counting failed", e.getCause());
} finally {
    pool.shutdown();
}
```

`merge` is atomic per key, so no update is lost. Calling `get()` on every future both waits for completion and rethrows a task's exception instead of losing it.
